#!/usr/bin/env bash
# Renders the live room's plate for the bar: the base in two halves (each under ten minutes),
# one pass per lamp, the surroundings for the pieces' reflections, and the jukebox.
# About 45 minutes on this machine. Then: node lobby/tools/pack-baked.mjs
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
run() { "$here/run.sh" "$@" 2>&1 | grep "saved\|rror"; }
run plate-juke - 96
run plate-env - 64
run plate-base - 64 0,0,0.5,1
run plate-base - 64 0.5,0,1,1
for i in 0 1 2 3 4; do run "plate-lamp$i" - 64; done
echo done > "$here/out/.plate-done"
